function simulate(layout, actions) {
  const W = 7,
    H = 7;
  const D = { N: [0, -1], S: [0, 1], E: [1, 0], W: [-1, 0] };
  const L = { white: "w", red: "r", green: "g", blue: "b" };
  let p = { x: layout.player.x, y: layout.player.y };
  let cr = layout.crates.map((c) => ({ id: c.id, x: c.x, y: c.y }));
  let open = {};
  layout.doors.forEach((d) => (open[d.id] = false));
  const at = (a, x, y) => a.find((o) => o.x === x && o.y === y);
  function compute() {
    let light = [];
    for (let y = 0; y < H; y++) {
      light.push([]);
      for (let x = 0; x < W; x++) light[y].push(new Set());
    }
    let lit = new Set();
    for (const l of layout.lamps) {
      let [dx, dy] = D[l.dir];
      let col = L[l.color];
      let x = l.x + dx,
        y = l.y + dy,
        n = 0;
      while (x >= 0 && y >= 0 && x < W && y < H && n < 50) {
        n++;
        if (at(layout.walls, x, y) || at(layout.lamps, x, y)) break;
        const d = at(layout.doors, x, y);
        if (d && !open[d.id]) break;
        const c = at(cr, x, y);
        if (c) {
          lit.add(c.id);
          light[y][x].add(col);
          break;
        }
        const g = at(layout.glass, x, y);
        if (g && g.color !== "white") col = L[g.color];
        light[y][x].add(col);
        x += dx;
        y += dy;
      }
    }
    return { light, lit };
  }
  function obs() {
    let st = compute();
    for (let it = 0; it < 5; it++) {
      for (const d of layout.doors) {
        const s = layout.sensors.find((s) => s.id === d.sensor);
        open[d.id] = st.light[s.y][s.x].has(L[d.color]);
      }
      st = compute();
    }
    return {
      player: { x: p.x, y: p.y },
      crates: cr.map((c) => ({ id: c.id, x: c.x, y: c.y, lit: st.lit.has(c.id) })),
      light: st.light.map((r) => r.map((s) => [...s].sort().join(""))),
      sensors: layout.sensors.map((s) => ({
        id: s.id,
        light: [...st.light[s.y][s.x]].sort().join(""),
      })),
      doors: layout.doors.map((d) => ({ id: d.id, open: open[d.id] })),
    };
  }
  function blocked(x, y) {
    if (x < 0 || y < 0 || x >= W || y >= H) return true;
    if (at(layout.walls, x, y) || at(layout.lamps, x, y) || at(layout.glass, x, y))
      return true;
    const d = at(layout.doors, x, y);
    if (d && !open[d.id]) return true;
    return false;
  }
  const out = [obs()];
  for (const a of actions) {
    const [dx, dy] = D[a];
    const nx = p.x + dx,
      ny = p.y + dy;
    if (!blocked(nx, ny)) {
      const c = at(cr, nx, ny);
      if (c) {
        const bx = nx + dx,
          by = ny + dy;
        if (!blocked(bx, by) && !at(cr, bx, by)) {
          c.x = bx;
          c.y = by;
          p = { x: nx, y: ny };
        }
      } else p = { x: nx, y: ny };
    }
    out.push(obs());
  }
  return out;
}

